import { Sequelize } from 'sequelize';
import config from './envConfig.js';

// Initialize Sequelize for PostgreSQL
const sequelize = new Sequelize(config.DB_DATABASE, config.DB_USER, config.DB_PASSWORD, {
  host: config.DB_HOST,
  port: Number(config.DB_PORT) || 5432,
  dialect: 'postgres',
  logging: false,
});

// Optional: helper to test the connection during startup
export async function testSequelizeConnection() {
  try {
    await sequelize.authenticate();
    console.log('✅ Connected to database with Sequelize');
    return true;
  } catch (error) {
    console.error('❌ Sequelize connection error:', error);
    throw error;
  }
}

export default sequelize;
